  const concha3 = SZGame2D.createSprite({ x: 460, y: 240, w: 48, h: 48, image: "concha" });
  const balde = SZGame2D.createSprite({ x: 560, y: 240, w: 48, h: 48, image: "balde" });
  // Quando acontecer
  SZGame2D.onKey("Enter", () => {
    SZGame2D.restart();
  }, "sua-ilha-quadro-6_events_0");
  SZGame2D.onOverlap(() => guia, () => concha1, () => {
    pegou1 = true;
    SZGame2D.destroySprite(concha1);
  }, "sua-ilha-quadro-6_events_1");
  SZGame2D.onOverlap(() => guia, () => concha2, () => {
    pegou2 = true;
    SZGame2D.destroySprite(concha2);
  }, "sua-ilha-quadro-6_events_2");
  SZGame2D.onOverlap(() => guia, () => concha3, () => {
    pegou3 = true;
    SZGame2D.destroySprite(concha3);
  }, "sua-ilha-quadro-6_events_3");
  SZGame2D.onOverlap(() => guia, () => balde, () => {
    if (pegou1) {
      if (pegou2) {
        if (pegou3) {
          cheio = true;
        }
      }
    }
  }, "sua-ilha-quadro-6_events_4");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    SZGame2D.topDown(guia, 4);
    SZGame2D.clampToScreen(guia, ctx);
    SZGame2D.clear();
    SZGame2D.drawLabel(ctx, "Pega-conchas", 20, 35, "#1d4f63", 18, "left");
    SZGame2D.drawLabel(ctx, "Pegue as três conchas e leve ao balde.", 20, 68, "#1d4f63", 18, "left");
    SZGame2D.drawSprite(ctx, concha1);
    SZGame2D.drawSprite(ctx, concha2);
    SZGame2D.drawSprite(ctx, concha3);
    SZGame2D.drawSprite(ctx, balde);
    if (cheio) {
      SZGame2D.drawLabel(ctx, "O balde do Nico está cheio.", 20, 120, "#1d4f63", 18, "left");
    }
    SZGame2D.drawSprite(ctx, guia);
  }, "sua-ilha-quadro-6_loops_0");
}, "__sz-project");
